# PostgreSQL Connection Pool in Node.js

## Installation

```bash
npm install pg
npm install dotenv  # for environment variables
```

## Basic Pool Configuration

```javascript
// db/pool.js
const { Pool } = require('pg');
require('dotenv').config();

const pool = new Pool({
  // Connection settings
  host:     process.env.DB_HOST || 'localhost',
  port:     parseInt(process.env.DB_PORT) || 5432,
  database: process.env.DB_NAME || 'mydb',
  user:     process.env.DB_USER || 'postgres',
  password: process.env.DB_PASSWORD,

  // Pool sizing
  min: 2,          // Minimum connections to keep alive
  max: 10,         // Maximum connections in pool

  // Timeout settings (all in milliseconds)
  connectionTimeoutMillis: 5000,   // Wait time to acquire connection from pool
  idleTimeoutMillis:       30000,  // Remove idle connections after 30s
  query_timeout:           10000,  // Cancel queries running longer than 10s
  statement_timeout:       10000,  // Server-side query timeout

  // SSL (for production)
  ssl: process.env.NODE_ENV === 'production'
    ? { rejectUnauthorized: true }
    : false,
});

module.exports = pool;
```

## Error Event Handling

```javascript
// db/pool.js (continued)

// Fires when an idle client encounters an unexpected error
pool.on('error', (err, client) => {
  console.error('Unexpected error on idle client:', err.message);
  // Do NOT throw here - it will crash the process
  // Log and let the pool remove the bad client automatically
});

// Optional: monitor pool lifecycle
pool.on('connect', (client) => {
  console.log('New client connected to pool');
  // Set session-level settings per connection
  client.query("SET search_path TO myschema, public");
});

pool.on('acquire', (client) => {
  console.debug('Client acquired from pool');
});

pool.on('remove', (client) => {
  console.log('Client removed from pool');
});
```

## Query Wrapper with Error Handling

```javascript
// db/query.js
const pool = require('./pool');

/**
 * Execute a query using an auto-released pool client
 */
async function query(text, params) {
  const start = Date.now();

  try {
    const result = await pool.query(text, params);
    const duration = Date.now() - start;
    console.debug('Query executed', { text, duration, rows: result.rowCount });
    return result;

  } catch (err) {
    handleQueryError(err, text);
    throw err; // Re-throw after logging
  }
}

function handleQueryError(err, queryText) {
  const errorMap = {
    '23505': `Duplicate key violation`,               // unique_violation
    '23503': `Foreign key violation`,                 // foreign_key_violation
    '23502': `Not null violation`,                    // not_null_violation
    '42P01': `Table does not exist`,                  // undefined_table
    '57014': `Query cancelled (statement timeout)`,   // query_canceled
    '08006': `Connection failure`,                    // connection_failure
    '08001': `Unable to connect to server`,           // sqlclient_unable_to_establish_sqlconnection
  };

  const message = errorMap[err.code] || err.message;
  console.error('Database error:', {
    code:    err.code,
    message: message,
    query:   queryText,
    detail:  err.detail,
  });
}

module.exports = { query };
```

## Transaction Helper

```javascript
// db/transaction.js
const pool = require('./pool');

/**
 * Run multiple queries in a transaction with automatic rollback on error
 */
async function withTransaction(callback) {
  const client = await pool.connect(); // Acquire dedicated client

  try {
    await client.query('BEGIN');

    const result = await callback(client); // Pass client to caller

    await client.query('COMMIT');
    return result;

  } catch (err) {
    await client.query('ROLLBACK');
    console.error('Transaction rolled back:', err.message);
    throw err;

  } finally {
    client.release(); // ALWAYS release back to pool
  }
}

module.exports = { withTransaction };
```

## Usage Examples

```javascript
// routes/users.js
const { query }           = require('../db/query');
const { withTransaction } = require('../db/transaction');

// Simple query
async function getUser(id) {
  const { rows } = await query(
    'SELECT * FROM users WHERE id = $1',
    [id]
  );
  return rows[0] ?? null;
}

// Transaction example
async function transferFunds(fromId, toId, amount) {
  return withTransaction(async (client) => {
    const { rows: [sender] } = await client.query(
      'SELECT balance FROM accounts WHERE id = $1 FOR UPDATE',
      [fromId]
    );

    if (!sender || sender.balance < amount) {
      throw new Error('Insufficient funds');
    }

    await client.query(
      'UPDATE accounts SET balance = balance - $1 WHERE id = $2',
      [amount, fromId]
    );

    await client.query(
      'UPDATE accounts SET balance = balance + $1 WHERE id = $2',
      [amount, toId]
    );

    return { success: true };
  });
}
```

## Graceful Shutdown

```javascript
// server.js
const pool = require('./db/pool');

async function shutdown(signal) {
  console.log(`${signal} received - shutting down`);

  // Stop accepting new requests first (Express example)
  server.close(async () => {
    try {
      await pool.end(); // Wait for active queries to finish, then close
      console.log('Pool closed successfully');
      process.exit(0);
    } catch (err) {
      console.error('Error closing pool:', err);
      process.exit(1);
    }
  });

  // Force exit if graceful shutdown takes too long
  setTimeout(() => process.exit(1), 10000);
}

process.on('SIGTERM', () => shutdown('SIGTERM'));
process.on('SIGINT',  () => shutdown('SIGINT'));
```

## Environment Variables (`.env`)

```bash
DB_HOST=localhost
DB_PORT=5432
DB_NAME=mydb
DB_USER=postgres
DB_PASSWORD=secret
NODE_ENV=development
```

## Key Rules to Remember

| Rule | Why |
|------|-----|
| Always `client.release()` in `finally` | Prevents pool exhaustion |
| Never `throw` in `pool.on('error')` | Avoids process crash |
| Use `$1, $2` placeholders | Prevents SQL injection |
| Set both `connectionTimeout` and `statement_timeout` | Prevents hung queries |
| Call `pool.end()` on shutdown | Ensures clean disconnection |

**Pool sizing guideline**: `max connections = (core_count * 2) + effective_spindle_count`, but start with 10 and tune based on monitoring.
